    public Advisor update( Advisor entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Advisor
	 * 
     * @param	id		UUID
     */
    public Advisor delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Advisor entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Firm
     * 
     * @param	parentId	UUID
     * @param	assignment 	WealthFirm 
     * @return	Advisor
     */
    public Advisor assignFirm( UUID parentId, WealthFirm assignment ) {
	    LOGGER.info("assigning Firm as " + assignment.toString() );

	    Advisor parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( WealthFirm.class, assignment.getWealthFirmId());

	    // ------------------------------------------
		// assign the Firm to the parent entity
		// ------------------------------------------ 
	    parentEntity.setFirm( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Firm
	 * 
	 * @param	parentId		UUID
	 * @return	Advisor
	 */
	public Advisor unAssignFirm( UUID parentId ) {
		Advisor parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Firm on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Firm on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFirm(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}

